SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state", "n_short", "n_price", "n_due", 'hold_ar' AS "route", 'overdue invoices' AS "verdict_reason"
FROM (SELECT "t29"."order_number", "t29"."customer", "t29"."channel", "t29"."fulfilling_warehouse", "t29"."value", "t29"."placed_date", "t29"."state", COALESCE("t29"."n_short", 0) AS "n_short", COALESCE("t29"."n_price", 0) AS "n_price", COALESCE("t35"."n_due", 0) AS "n_due"
        FROM (SELECT "t17"."order_number", "t17"."customer", "t17"."channel", "t17"."fulfilling_warehouse", "t17"."value", "t17"."placed_date", "t17"."state", "t17"."n_short", "t28"."n_price"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "t16"."n_short"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                FROM (SELECT "t11"."order_number", "t11"."customer", "t11"."channel", "t11"."fulfilling_warehouse", "t11"."value", "t11"."placed_date", "t11"."state", "t11"."line_no", "t11"."item", "t11"."quantity", "t11"."unit_price", "t11"."ext_sales_price", "t11"."warehouse", "t11"."sold_date", "t11"."customer0", "t11"."channel0", "t11"."as_of_date", "t11"."quantity_on_hand", "t11"."_ttrp_g_n9_0", "t11"."_ttrp_g_n9_1", "t11"."_ttrp_latest_n9", "t12"."warehouse" AS "warehouse0", "t12"."from_date", "t12"."to_date", "t12"."reason", COALESCE("t11"."quantity_on_hand", 0) AS "on_hand", "t12"."warehouse" IS NOT NULL AS "outage"
                                        FROM (SELECT *
                                                FROM (SELECT "t4"."order_number", "t4"."customer", "t4"."channel", "t4"."fulfilling_warehouse", "t4"."value", "t4"."placed_date", "t4"."state", "t4"."line_no", "t4"."item", "t4"."quantity", "t4"."unit_price", "t4"."ext_sales_price", "t4"."warehouse", "t4"."sold_date", "t4"."customer0", "t4"."channel0", "t4"."as_of_date", "t4"."quantity_on_hand", "t4"."_ttrp_g_n9_0", "t4"."_ttrp_g_n9_1", "t9"."_ttrp_latest_n9"
                                                        FROM (SELECT "t3"."order_number", "t3"."customer", "t3"."channel", "t3"."fulfilling_warehouse", "t3"."value", "t3"."placed_date", "t3"."state", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."ext_sales_price", "t3"."warehouse", "t3"."sold_date", "t3"."customer0", "t3"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t3"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t3"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t3"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t3"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                                FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t2"
                                                                            INNER JOIN "sales_line" ON "t2"."order_number" = "sales_line"."order_number") AS "t3"
                                                                    LEFT JOIN "inventory" ON "t3"."item" = "inventory"."item" AND "t3"."warehouse" = "inventory"."warehouse") AS "t4"
                                                            INNER JOIN (SELECT CASE WHEN "t7"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t7"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                                                FROM (SELECT "t6"."order_number", "t6"."customer", "t6"."channel", "t6"."fulfilling_warehouse", "t6"."value", "t6"."placed_date", "t6"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t6"
                                                                            INNER JOIN "sales_line" AS "sales_line0" ON "t6"."order_number" = "sales_line0"."order_number") AS "t7"
                                                                    LEFT JOIN "inventory" AS "inventory0" ON "t7"."item" = "inventory0"."item" AND "t7"."warehouse" = "inventory0"."warehouse"
                                                                GROUP BY CASE WHEN "t7"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."order_number" AS VARCHAR) END, CASE WHEN "t7"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."line_no" AS VARCHAR) END) AS "t9" ON "t4"."_ttrp_g_n9_0" = "t9"."_ttrp_g_n9_0" AND "t4"."_ttrp_g_n9_1" = "t9"."_ttrp_g_n9_1") AS "t10"
                                                WHERE "t10"."as_of_date" = "t10"."_ttrp_latest_n9" OR "t10"."_ttrp_latest_n9" IS NULL) AS "t11"
                                            LEFT JOIN (SELECT *
                                                FROM "warehouse_outage"
                                                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t12" ON "t11"."warehouse" = "t12"."warehouse") AS "t13"
                                WHERE "t13"."outage" OR "t13"."on_hand" < "t13"."quantity"
                                GROUP BY "order_number") AS "t16" ON "t0"."order_number" = "t16"."order_number") AS "t17"
                    LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                        FROM (SELECT "t20"."order_number", "t20"."line_no", "t20"."item", "t20"."unit_price", "t20"."customer", "t20"."channel", "t20"."placed_date", "t24"."order_number" AS "order_number0", "t24"."line_no" AS "line_no0", "t24"."price"
                                FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t19"."customer", "t19"."channel", "t19"."placed_date"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t19"
                                            INNER JOIN "sales_line" AS "sales_line1" ON "t19"."order_number" = "sales_line1"."order_number") AS "t20"
                                    INNER JOIN (SELECT "t23"."order_number", "t23"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                        FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t22"."customer", "t22"."channel", "t22"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t22"
                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t22"."order_number" = "sales_line2"."order_number") AS "t23"
                                            LEFT JOIN "customer_price" ON "t23"."item" = "customer_price"."item" AND "t23"."customer" = "customer_price"."customer" AND "t23"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t23"."placed_date" <= "customer_price"."valid_to")
                                            LEFT JOIN "price_list" ON "t23"."item" = "price_list"."item" AND "t23"."channel" = "price_list"."channel" AND "t23"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t23"."placed_date" <= "price_list"."valid_to")) AS "t24" ON "t20"."order_number" = "t24"."order_number" AND "t20"."line_no" = "t24"."line_no") AS "t25"
                        WHERE "t25"."price" IS NULL OR ABS("t25"."unit_price" - "t25"."price") > :tolerance
                        GROUP BY "order_number0") AS "t28" ON "t17"."order_number" = "t28"."order_number") AS "t29"
            LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                FROM (SELECT "t31"."order_number", "t31"."customer", "t31"."channel", "t31"."fulfilling_warehouse", "t31"."value", "t31"."placed_date", "t31"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t31"
                            INNER JOIN "invoice" ON "t31"."customer" = "invoice"."customer") AS "t32"
                WHERE "t32"."status" = 'open' AND "t32"."due" < :as_of
                GROUP BY "order_number") AS "t35" ON "t29"."order_number" = "t35"."order_number") AS "t36"
WHERE "t36"."n_due" > 0
